-- CyberVerse 95-topic curriculum migration
-- Uses the existing lessons/topics tables. No DROP, TRUNCATE, or DELETE statements.
-- Existing lesson IDs 1-6 and topic IDs 1-18 are retained; rows are updated in place.
-- Back up the live database before running. Run once in the intended CyberVerse database.
-- CyberVerse curriculum replacement migration (MySQL 8+)
-- DESTRUCTIVE to lesson-related data: clears bookmarks, notes, quiz attempts,
-- quizzes/questions, certificates, topics, and lessons before inserting the
-- 9-module / 95-topic curriculum from this file.
-- Preserves: users and all table definitions. Also leaves labs, lab_results,
-- achievements, user_achievements, daily_challenges, and user_challenges intact.
-- Confirm the selected schema in MySQL Workbench before running.
-- A separate live backup is required. Run this script only once.

START TRANSACTION;

-- Remove dependent learner/content rows first to satisfy foreign keys.
DELETE FROM quiz_results;
DELETE FROM questions;
DELETE FROM quizzes;
DELETE FROM bookmarks;
DELETE FROM notes;
DELETE FROM certificates;
DELETE FROM topics;
DELETE FROM lessons;





-- Curriculum replacement complete: 9 lessons and 95 topics are inserted.
COMMIT;
